// =====================================================================================
//  CONFIG - everything you need to change lives here.
//  Secrets do NOT live here; they are n8n credentials (Telegram, Supabase, Apify,
//  RapidAPI, Bland). This node holds the non-secret settings only.
// =====================================================================================
return [{ json: { config: {

  // --- the mountain -----------------------------------------------------------------
  resortUrl:      'https://www.snow-forecast.com/resorts/Niseko/6day/top',
  resortName:     'Niseko Grand Hirafu',
  liftLat:        42.8615,       // Hirafu gondola, used for the boot-walk ranking
  liftLng:        140.6982,

  // --- the trigger ------------------------------------------------------------------
  snowCm:         40,            // overnight dump that counts
  coldC:          -10,           // must stay at or below this...
  coldRunDays:    3,             // ...for this many days straight
  tripNights:     5,

  // --- travel -----------------------------------------------------------------------
  homeAirport:    'PER',
  arriveAirport:  'CTS',         // Sapporo New Chitose
  adults:         4,

  // --- the arrival sequence ---------------------------------------------------------
  transferLeadMins: 30,          // book the taxi this long before touchdown
  beerLeadMins:     10,          // order the beers this many minutes from the chalet

  // Saved contacts. Swap these for the operators you actually use.
  taxiContact:  { name: 'Niseko Taxi',        phone: 'YOUR_PHONE_NUMBER' },
  beerContact:  { name: 'Hirafu Bottle Shop', phone: 'YOUR_PHONE_NUMBER' },

  // --- who gets told ----------------------------------------------------------------
  telegramChatId: 'YOUR_TELEGRAM_CHAT_ID',
} }}];

// AeroDataBox "Flight Status (single day)" returns an ARRAY of FlightContract.
// Verified against their OpenAPI spec (host aerodatabox.p.rapidapi.com):
//   arrival.scheduledTime / revisedTime / predictedTime / runwayTime, plus .status
// revisedTime is the live one; fall back through predicted -> scheduled.
const raw = $input.first().json;
const arr = Array.isArray(raw) ? raw : (raw ? [raw] : []);
if (!arr.length) {
  return [{ json: { found: false, note: 'no flight returned for that number/date' } }];
}
const f = arr[0];
const a = f.arrival || {};
const pick = function (t) {
  if (!t) return null;
  return t.utc || t.local || null;
};
const iso = pick(a.revisedTime) || pick(a.predictedTime) || pick(a.scheduledTime);
const etaMs = iso ? Date.parse(String(iso).replace(' ', 'T')) : NaN;
const mins = isNaN(etaMs) ? null : Math.round((etaMs - Date.now()) / 60000);

return [{ json: {
  found: true,
  flightNumber: f.number || null,
  status: f.status || null,
  arrivalAirport: (a.airport || {}).name || null,
  terminal: a.terminal || null,
  baggageBelt: a.baggageBelt || null,
  etaIso: iso,
  minsToLanding: mins,
  usedField: pick(a.revisedTime) ? 'revisedTime'
           : pick(a.predictedTime) ? 'predictedTime' : 'scheduledTime',
} }];

