parameters.jsCode:
// Accepts a location ping from OwnTracks (HTTP mode) OR an iOS Shortcut.
// OwnTracks posts at minimum: _type:"location", lat, lon, tst (epoch seconds), tid.
// A Shortcut can post {lat, lon} - both shapes are handled.
const b = $input.first().json.body || $input.first().json || {};
const lat = b.lat != null ? Number(b.lat) : (b.latitude != null ? Number(b.latitude) : null);
const lng = b.lon != null ? Number(b.lon) : (b.lng != null ? Number(b.lng)
          : (b.longitude != null ? Number(b.longitude) : null));

if (lat == null || lng == null || isNaN(lat) || isNaN(lng)) {
  throw new Error('location ping had no usable lat/lon - got keys: ' + Object.keys(b).join(','));
}
return [{ json: {
  lat: lat,
  lng: lng,
  source: b._type === 'location' ? 'owntracks' : 'shortcut',
  tracker: b.tid || null,
  accuracy_m: b.acc != null ? b.acc : null,
  fixedAt: b.tst ? new Date(b.tst * 1000).toISOString() : new Date().toISOString(),
} }];

// OSRM public router: /route/v1/driving/{lng},{lat};{lng},{lat}?overview=false
// Free and keyless. Swap the base URL for Google Distance Matrix if you want SLAs.
const r = $input.first().json;
const loc = $('Read the location ping').first().json;
const trip = $('Find the trip in transit').first().json;

const route = (r.routes || [])[0];
if (!route) {
  return [{ json: { ok: false, note: 'OSRM returned no route', minsToChalet: null } }];
}
const mins = Math.round(route.duration / 60);
return [{ json: {
  ok: true,
  tripId: trip.id,
  minsToChalet: mins,
  km: +(route.distance / 1000).toFixed(1),
  from: { lat: loc.lat, lng: loc.lng },
  to: { lat: trip.chalet_lat, lng: trip.chalet_lng },
  beersAlreadyOrdered: !!trip.beers_ordered_at,
} }];

